			function doResrceNmDpcnCheck(){
			    
			    if(!validate()) return;
			    
			    // 자원명 중복 체크 서브미션 호출
			    util.Submit.send(app, "subDpcn", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            // 자원 중복 여부
			            var dpcnYn = util.DataMap.getValue(app, "dmDpcnYn", "DPCN_YN");
			            
			            
			            // 사용 여부
			            var useYn = util.DataMap.getValue(app, "dmDpcnYn", "USE_YN");
			            
			            
			            if(dpcnYn == "Y"){
			                
			                var msg = "";
			                
			                if(useYn == "Y"){
			                    msg = "사용 중 으로 등록되어있는 자원 입니다.";
			                }else{
			                    msg = "사용 안함 으로  등록되어있는 자원 입니다.";
			                }
			                
			                util.Msg.alert(app, msg);
			                
			                return false;
			            }else if(dpcnYn == "N"){
			                //util.Msg.alert(app, "중복 아님 등록 가능");
			                doSave();
			            }
			            
			            
			        }
			    });
			    
			}


